//!
//! Unified web server for op-dbus-v2.

use std::net::SocketAddr;
use std::sync::Arc;
use tracing::info;
use tracing_subscriber::{EnvFilter, FmtSubscriber};

use op_web::routes;
use op_web::AppState;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // Initialize logging with environment filter (RUST_LOG)
    // Default to info if not set
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));

    let _ = FmtSubscriber::builder()
        .with_env_filter(filter)
        .with_target(false)
        .with_thread_ids(false)
        .compact()
        .try_init();

    info!("Starting op-web server...");
    info!("Version: {}", env!("CARGO_PKG_VERSION"));

    // Absolute Base: without a valid schema catalog in shared memory, the entity does not exist.
    const SHM_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";
    match std::fs::metadata(SHM_SCHEMA_PATH) {
        Ok(meta) if meta.len() > 2 => {
            info!(
                path = SHM_SCHEMA_PATH,
                bytes = meta.len(),
                "Schema catalog present in shared memory"
            );
        }
        _ => {
            tracing::error!(
                path = SHM_SCHEMA_PATH,
                "FATAL: Schema catalog missing from shared memory. Start projection_server first."
            );
            std::process::exit(1);
        }
    }

    let state = Arc::new(AppState::new().await?);
    state.clone().start_event_bridge();
    state.clone().start_system_monitor();
    let app = routes::create_router(state);

    let port = std::env::var("PORT")
        .unwrap_or_else(|_| "8080".to_string())
        .parse::<u16>()
        .unwrap_or(8080);
    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    info!("Listening on http://{}", addr);
    info!("WebSocket available at ws://{}/ws", addr);
    info!("API available at http://{}/api", addr);

    let listener = tokio::net::TcpListener::bind(addr).await?;
    axum::serve(
        listener,
        app.into_make_service_with_connect_info::<SocketAddr>(),
    )
    .await?;

    Ok(())
}

